code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = {v:n for v,n in counts.items() if v != bg}
    if not fg:
        return g

    # Sparse marks in a framed panel: extend each mark to the frame and copy
    # its row into the aligned neighboring panel.
    sparse = min(fg, key=fg.get)
    frame = max(fg, key=fg.get)
    marks = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == sparse]
    if len(marks) > 1 and len(fg) >= 2:
        lower = next((r for r in range(h) if grid[r][-1] == frame), None)
        if lower is not None and any(r >= lower for r,c in marks):
            upper = 0
            for r,c in marks:
                # Horizontal ray to the frame; the mark becomes the 4 marker.
                for cc in range(c+1, w):
                    if grid[r][cc] == frame:
                        break
                    g[r][cc] = sparse
                g[r][c] = 4
                rr = upper + (r-lower)
                if 0 <= rr < h:
                    for cc in range(w):
                        if grid[rr][cc] != frame:
                            g[rr][cc] = sparse
            return g

    # A single colored mark and paired edge bars: each bar sends a ray inward.
    seed_color = sparse
    seed = marks[0] if len(marks) == 1 else None
    bars = []
    for r in (0, h-1):
        for c in range(w-1):
            v = grid[r][c]
            if v != bg and v == grid[r][c+1] and (seed is None or v != seed_color):
                bars.append((r,c))
    for r,c in bars:
        ray = range(1, h) if r == 0 else range(h-2, -1, -1)
        for rr in ray:
            if seed == (rr,c):
                break
            g[rr][c] = seed_color
    if seed is not None:
        r,c = seed
        g[r][c] = 4
    return g
'''
